const tabId = 1148881640;
const snapshot = await browser.snapshot({ tabId });
console.log(snapshot.text.slice(0, 3000));

const tabId = 1148881640;
const appLinks = await browserjs(tabId, () => {
  const links = Array.from(document.querySelectorAll('a'));
  return links.map(a => ({
    text: a.innerText?.trim(),
    href: a.href,
    ariaLabel: a.getAttribute('aria-label')
  })).filter(l => 
    /app|ios|apple|mobile|iphone/i.test(l.text) || 
    /app|ios|apple|mobile|iphone/i.test(l.href) || 
    /app|ios|apple|mobile|iphone/i.test(l.ariaLabel || '')
  );
});
console.log("Matching links:", JSON.stringify(appLinks, null, 2));

const tabId = 1148881640;
await tool.navigate({ tabId, url: "https://www.recreation.gov/mobile-app" });
await tool.wait_for({ tabId, condition: "load_state", value: "load" });
const text = await browser.snapshot({ tabId });
console.log(text.text.slice(0, 3000));

const tabId = 1148881640;
const appStoreLink = await browserjs(tabId, () => {
  const link = document.querySelector('a[aria-label*="App Store"], a[href*="apple.com"], a[href*="apps.apple.com"]') || 
               Array.from(document.querySelectorAll('a')).find(a => a.innerText?.includes('App Store') || a.querySelector('img[alt*="App Store"]'));
  return {
    href: link?.href,
    target: link?.target,
    outerHTML: link?.outerHTML
  };
});
console.log("App Store link info:", JSON.stringify(appStoreLink, null, 2));

const tabId = 1148881640;
await tool.navigate({ tabId, url: "https://itunes.apple.com/us/app/recreation-gov/id1440487780?ls=1&mt=8" });
await tool.wait_for({ tabId, condition: "load_state", value: "load" });
const text = await browser.snapshot({ tabId });
console.log("Current URL:", await browserjs(tabId, () => window.location.href));
console.log("Page snapshot preview:", text.text.slice(0, 1500));

const tabId = 1148881640;
const details = await browserjs(tabId, () => {
  const h1 = document.querySelector('h1')?.innerText?.trim();
  const subtitle = document.querySelector('h2')?.innerText?.trim();
  const description = document.querySelector('.section__description')?.innerText?.trim() || document.querySelector('[data-test-id="description"]')?.innerText?.trim();
  return {
    title: document.title,
    url: window.location.href,
    h1,
    subtitle,
    description: description ? description.slice(0, 300) : null
  };
});
console.log("App Details:", JSON.stringify(details, null, 2));

